<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Invoice <?= esc($invoice['invoice_no']) ?></title><style>
@page{size:80mm auto;margin:3mm}*{box-sizing:border-box}body{width:74mm;margin:0 auto;font-family:"DejaVu Sans",monospace;font-size:9px;color:#111}.toolbar{position:sticky;top:0;background:#fff;padding:6px 0;text-align:center}.toolbar button{border:0;border-radius:4px;padding:7px 12px;background:#111;color:white;font-size:10px}.receipt{text-align:center}.receipt img{max-width:45mm;max-height:18mm;object-fit:contain}.receipt h1{font-size:13px;margin:5px}.rule{border-top:1px dashed #111;margin:7px 0}.row{display:flex;justify-content:space-between;gap:8px;margin:3px 0}.left{text-align:left}.right{text-align:right}.wrap{word-break:break-word}.total{font-size:11px;font-weight:bold}.items{width:100%;border-collapse:collapse}.items td{padding:3px 0;vertical-align:top}.thanks{margin-top:12px;line-height:1.5}@media print{.toolbar{display:none}body{width:74mm}}
</style></head><body><div class="toolbar"><button onclick="window.print()">Cetak thermal</button></div><main class="receipt"><?php if ($logoData): ?><img src="<?= $logoData ?>" alt="Logo"><?php else: ?><h1><?= esc($siteName) ?></h1><?php endif; ?><div><?= esc($invoice['branch_name'] ?? $siteName) ?></div><?php if ($invoice['branch_phone'] || $publicPhone): ?><div><?= esc($invoice['branch_phone'] ?: $publicPhone) ?></div><?php endif; ?><div class="rule"></div><strong>INVOICE</strong><div class="row"><span>No.</span><span><?= esc($invoice['invoice_no']) ?></span></div><div class="row"><span>Tanggal</span><span><?= esc(date('d-m-Y H:i')) ?></span></div><div class="row"><span>Periode</span><span><?= esc($invoice['period']) ?></span></div><div class="row"><span>Pelanggan</span><span><?= esc($invoice['customer_code']) ?></span></div><div class="left wrap"><?= esc($invoice['full_name']) ?></div><div class="rule"></div><table class="items"><tr><td class="left"><?= esc($invoice['plan_name'] ?: 'Layanan internet') ?></td><td class="right"><?= esc(mynet_money($invoice['amount'])) ?></td></tr><?php if ((float) $invoice['discount'] > 0): ?><tr><td class="left">Diskon</td><td class="right">-<?= esc(mynet_money($invoice['discount'])) ?></td></tr><?php endif; ?></table><div class="rule"></div><div class="row total"><span>Total</span><span><?= esc(mynet_money($invoice['total'])) ?></span></div><div class="row"><span>Dibayar</span><span><?= esc(mynet_money($paid)) ?></span></div><div class="row total"><span>Sisa</span><span><?= esc(mynet_money($balance)) ?></span></div><div class="row"><span>Jatuh tempo</span><span><?= esc($invoice['due_date']) ?></span></div><div class="rule"></div><div class="thanks">Terima kasih.<br><?= esc($siteName) ?></div></main></body></html>
